interaction.user_prompt:
[tool_result Bash] package main

import (
	"os"
	"path/filepath"
	"testing"
)

// writeFiles creates each name in dir with the given content.
func writeFiles(t *testing.T, dir string, content string, names ...string) {
	t.Helper()
	for _, name := range names {
		if err := os.WriteFile(filepath.Join(dir, name), []byte(content), 0644); err != nil {
			t.Fatal(err)
		}
	}
}

// readFile returns the content of path, failing the test if it cannot be read.
func readFile(t *testing.T, path string) string {
	t.Helper()
	b, err := os.ReadFile(path)
	if err != nil {
		t.Fatal(err)
	}
	return string(b)
}

// fileNamed returns the entry of dir called name.
func fileNamed(t *testing.T, dir, name string) file {
	t.Helper()
	files, err := readDirectory(dir)
	if err != nil {
		t.Fatal(err)
	}
	for _, f := range files {
		if f.Name == name {
			return f
		}
	}
	t.Fatalf("%s not found in %s", name, dir)
	return file{}
}

func TestReadDirectoryMarksParent(t *testing.T) {
	dir := t.TempDir()
	writeFiles(t, dir, "x", "a")

	files, err := readDirectory(dir)
	if err != nil {
		t.Fatal(err)
	}
	if len(files) != 2 || !files[0].IsParent || files[0].Name != ".." {
		t.Fatalf("expected '..' marked as parent first, got %+v", files)
	}
	if files[1].IsParent {
		t.Fatalf("regular entry marked as parent: %+v", files[1])
	}
}

Make copy, move and delete safe to use

- Mark the synthetic ".." entry with IsParent and exclude it from
  selection and from every operation; Alt+D on ".." used to run
  os.RemoveAll on the parent directory.
- Plan copy/move batches before touching anything: planBatch splits
  them into clean files, conflicts and rejected files (source equal to
  destination, a directory into itself). Copying with both panes on the
  same directory used to truncate the source files to zero bytes.
- Resolve overwrite conflicts one file at a time and run the whole batch
  (clean + overwritten) once every conflict is decided. Previously
  answering the first prompt overwrote all remaining conflicts, and
  non-conflicting files in a batch with conflicts were silently dropped.
- transferFiles re-checks the safety rules and reports every error
  instead of stopping at the first one.
- Add fs_test.go and update_test.go, the first tests in the repo.

